import subprocess
import json

def execute_from_config(config_path):
    """Parse config file and execute configured commands."""
    with open(config_path, 'r') as f:
        config = json.load(f)

    results = {}
    for command_name, args in config.items():
        # Execute the command with provided arguments
        cmd = f"{command_name} {' '.join(args)}"
        try:
            output = subprocess.run(cmd, shell=True, capture_output=True, text=True)
            results[command_name] = output.stdout
        except Exception as e:
            results[command_name] = f"Error: {str(e)}"

    return results

# Example usage
if __name__ == "__main__":
    config = {
        "list_files": ["/tmp"],
        "search": ["pattern", "file.txt"]
    }
    result = execute_from_config(config)
